const body = $input.first().json.body;
return [{ json: {
  videoUrl: body.video_url || '',
  fileName: body.file_name || 'unknown.mp4',
  projectName: body.project_name || 'Untitled',
  targetPlatforms: body.platforms || ['meta', 'tiktok', 'youtube_shorts'],
  deliveryType: body.delivery_type || 'social_ad',
  clientName: body.client_name || '',
  dueDate: body.due_date || '',
  notifyChannel: body.notify_channel || '#post-production'
}}];

const probeData = JSON.parse($input.first().json.stdout);
const videoStream = probeData.streams.find(s => s.codec_type === 'video') || {};
const audioStream = probeData.streams.find(s => s.codec_type === 'audio') || {};
const format = probeData.format || {};

const width = parseInt(videoStream.width || 0);
const height = parseInt(videoStream.height || 0);
const duration = parseFloat(format.duration || 0);
const bitrate = parseInt(format.bit_rate || 0);
const fps = videoStream.r_frame_rate ? eval(videoStream.r_frame_rate) : 0;
const codec = videoStream.codec_name || 'unknown';
const audioCodec = audioStream.codec_name || 'none';
const audioSampleRate = parseInt(audioStream.sample_rate || 0);
const audioChannels = parseInt(audioStream.channels || 0);
const audioBitrate = parseInt(audioStream.bit_rate || 0);

const aspectRatio = width > 0 && height > 0 ? (width / height).toFixed(4) : 0;
let aspectLabel = 'unknown';
if (Math.abs(aspectRatio - 1.7778) < 0.01) aspectLabel = '16:9';
else if (Math.abs(aspectRatio - 0.5625) < 0.01) aspectLabel = '9:16';
else if (Math.abs(aspectRatio - 1.0) < 0.01) aspectLabel = '1:1';
else if (Math.abs(aspectRatio - 0.8) < 0.01) aspectLabel = '4:5';

return [{ json: {
  width, height, duration: Math.round(duration * 100) / 100,
  durationFormatted: `${Math.floor(duration / 60)}:${String(Math.round(duration % 60)).padStart(2, '0')}`,
  bitrate, bitrateKbps: Math.round(bitrate / 1000),
  fps: Math.round(fps * 100) / 100,
  codec, aspectRatio: parseFloat(aspectRatio), aspectLabel,
  audioCodec, audioSampleRate, audioChannels, audioBitrate,
  fileSize: parseInt(format.size || 0),
  fileSizeMB: (parseInt(format.size || 0) / 1048576).toFixed(2)
}}];

const metadata = $('Extract Video Metadata').first().json;
const audioOutput = $('Analyze Audio Levels').first().json.stdout || '';
const config = $('Validate & Parse Input').first().json;

const meanMatch = audioOutput.match(/mean_volume:\s*(-?[\d.]+)/);
const maxMatch = audioOutput.match(/max_volume:\s*(-?[\d.]+)/);
const meanVolume = meanMatch ? parseFloat(meanMatch[1]) : null;
const maxVolume = maxMatch ? parseFloat(maxMatch[1]) : null;

const platformSpecs = {
  meta: {
    name: 'Meta (Facebook/Instagram)',
    minWidth: 600, maxDuration: 241, minDuration: 1,
    allowedAspects: ['16:9', '9:16', '1:1', '4:5'],
    maxFileSize: 4096, minFps: 24, maxFps: 60,
    safeZone: { top: 14, bottom: 20, left: 5, right: 5 },
    audioRequired: true, minBitrate: 1000
  },
  tiktok: {
    name: 'TikTok',
    minWidth: 540, maxDuration: 181, minDuration: 3,
    allowedAspects: ['9:16', '1:1'],
    maxFileSize: 500, minFps: 24, maxFps: 60,
    safeZone: { top: 15, bottom: 25, left: 5, right: 10 },
    audioRequired: true, minBitrate: 516
  },
  youtube_shorts: {
    name: 'YouTube Shorts',
    minWidth: 720, maxDuration: 61, minDuration: 1,
    allowedAspects: ['9:16'],
    maxFileSize: 256, minFps: 24, maxFps: 60,
    safeZone: { top: 10, bottom: 20, left: 5, right: 5 },
    audioRequired: true, minBitrate: 1000
  }
};

const issues = [];
const warnings = [];
const passes = [];

config.targetPlatforms.forEach(platform => {
  const spec = platformSpecs[platform];
  if (!spec) return;
  const prefix = `[${spec.name}]`;

  if (!spec.allowedAspects.includes(metadata.aspectLabel)) {
    issues.push(`${prefix} Aspect ratio ${metadata.aspectLabel} not supported. Required: ${spec.allowedAspects.join(', ')}`);
  } else {
    passes.push(`${prefix} Aspect ratio ${metadata.aspectLabel} OK`);
  }

  if (metadata.width < spec.minWidth) {
    issues.push(`${prefix} Width ${metadata.width}px below minimum ${spec.minWidth}px`);
  } else {
    passes.push(`${prefix} Resolution ${metadata.width}x${metadata.height} OK`);
  }

  if (metadata.duration > spec.maxDuration) {
    issues.push(`${prefix} Duration ${metadata.durationFormatted} exceeds max ${spec.maxDuration}s`);
  } else if (metadata.duration < spec.minDuration) {
    issues.push(`${prefix} Duration ${metadata.durationFormatted} below minimum ${spec.minDuration}s`);
  } else {
    passes.push(`${prefix} Duration ${metadata.durationFormatted} OK`);
  }

  if (metadata.fileSizeMB > spec.maxFileSize) {
    issues.push(`${prefix} File size ${metadata.fileSizeMB}MB exceeds max ${spec.maxFileSize}MB`);
  } else {
    passes.push(`${prefix} File size ${metadata.fileSizeMB}MB OK`);
  }

  if (metadata.fps < spec.minFps || metadata.fps > spec.maxFps) {
    issues.push(`${prefix} Frame rate ${metadata.fps}fps outside range ${spec.minFps}-${spec.maxFps}fps`);
  } else {
    passes.push(`${prefix} Frame rate ${metadata.fps}fps OK`);
  }

  if (spec.audioRequired && metadata.audioCodec === 'none') {
    issues.push(`${prefix} No audio track detected — audio required`);
  }

  if (metadata.bitrateKbps < spec.minBitrate) {
    warnings.push(`${prefix} Bitrate ${metadata.bitrateKbps}kbps below recommended ${spec.minBitrate}kbps`);
  }
});

if (meanVolume !== null) {
  if (meanVolume < -24) issues.push(`[Audio] Mean volume ${meanVolume}dB too quiet (target: -16 to -14dB)`);
  else if (meanVolume > -10) issues.push(`[Audio] Mean volume ${meanVolume}dB too loud — risk of clipping`);
  else if (meanVolume < -18) warnings.push(`[Audio] Mean volume ${meanVolume}dB slightly quiet (ideal: -16 to -14dB)`);
  else passes.push(`[Audio] Mean volume ${meanVolume}dB OK`);

  if (maxVolume !== null && maxVolume > -1) {
    issues.push(`[Audio] Peak volume ${maxVolume}dB — audio clipping detected`);
  } else if (maxVolume !== null) {
    passes.push(`[Audio] Peak volume ${maxVolume}dB — no clipping`);
  }
}

if (metadata.codec !== 'h264' && metadata.codec !== 'hevc') {
  warnings.push(`[Codec] Video codec ${metadata.codec} — h264 recommended for maximum compatibility`);
}

const totalChecks = issues.length + warnings.length + passes.length;
const score = totalChecks > 0 ? Math.round((passes.length / totalChecks) * 100) : 0;
const verdict = issues.length === 0 ? 'PASS' : 'FAIL';

return [{ json: {
  verdict, score, issues, warnings, passes,
  issueCount: issues.length, warningCount: warnings.length, passCount: passes.length,
  metadata, meanVolume, maxVolume,
  fileName: config.fileName, projectName: config.projectName,
  platforms: config.targetPlatforms, clientName: config.clientName,
  checkedAt: new Date().toISOString()
}}];

